assert EA3_MAXV <= EA_TK_MAXV

EA_ENGINES["v3"] = min(EA3_MAX_T, EA2_MAX_T)


def _ea3_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace=None, pdl13=0,
                      kern=("ea3_w13", "ea3_w2"), recs=("w13r", "w2r")):
    """out [T, H] for 1 <= T <= EA3_MAX_T, _ea2_forward_core's contract with v3's kernels: ea3_w13 (work map + w13 +
    silu -> h [8T, I], one row per sorted local route; local_ids [T, 8]), ea3_w2 (PDL on ea3_w13 -> y in master's cache3
    layout; its grid ea["g2_t"][T] when set, as v1 / v2 take it, else ea["grid"]), then the combine (the CUDA one,
    PDL-linked to ea3_w2, when ea["cmb_t"][T] is set, else the problem's _post_norm_combine_kernel). topk_ids [T, 8]
    int32: an id is local iff start <= id < start + count. kern / recs: the (w13, w2) entry points and record keys
    (v4: ea4_core.py, v5: ea5_core.py)."""
    ext = ea["ext"]
    k13, k2 = getattr(ext, kern[0]), getattr(ext, kern[1])
    tokens, hidden = x.shape
    inter = ea["inter"]
    h = torch.empty((tokens * TOP_K, inter), device=x.device, dtype=torch.bfloat16)
    local_ids = torch.empty((tokens, TOP_K), device=x.device, dtype=torch.int32)
    y = torch.empty((tokens * TOP_K, hidden), device=x.device, dtype=torch.bfloat16)
    if trace is not None:
        trace(f"before {kern[0]}")
    k13(x, topk_ids, ea[recs[0]], ea["gs13"], h, local_ids, ea["ws13"], ea["tk13"], ea["err"], tokens, start, count,
        ea["grid"], ea["dq"], pdl13)
    if trace is not None:
        trace(f"after {kern[0]} / before {kern[1]}")
    k2(h, topk_ids, ea[recs[1]], ea["gs2"], y, ea["ws2"], ea["tk2"], ea["err"], tokens, start, count,
       ea.get("g2_t", {}).get(tokens, ea["grid"]), ea["dq"], ea["pdl"])
    if trace is not None:
        trace(f"after {kern[1]} / before post-expert norm")
    out = torch.empty((tokens, hidden), device=x.device, dtype=torch.bfloat16)
    tw32 = topk_weights.to(torch.float32).contiguous()
    if ea.get("cmb_t", {}).get(tokens, 0):  # CUDA twin of the Triton combine, PDL-linked to K2
        ext.ea_combine(y, local_ids, tw32, norm_w, out, POST_NORM_EPS, 1)
    else:
        _post_norm_combine_kernel[(tokens,)](
            y, local_ids, tw32, norm_w, out, hidden, POST_NORM_EPS,
            TOP_K_C=TOP_K, BLOCK_H=triton.next_power_of_2(hidden), num_warps=8)
    if trace is not None:
        trace("after post-expert norm")
    return out
