WG_EPI_BYTES = {True: 128 * (64 * 2 + 16), False: 128 * (128 * 2 + 16)}
WG_SMEM = {g: 1024 + WG_STAGES * WG_STAGE_BYTES + WG_EPI_BYTES[g] for g in (True, False)}
